  /**
   * @param loansAccount Loan account data used for the request
   * @param loansAccountTemplate Loan account template for getting product default values
   * @param calendarOptions Calendar options
   * @param locale String to send to backend
   * @param dateFormat String with date format to manage dates
   * @returns Object with Loan Account payload data.
   */
  buildLoanRequestPayload(
    loansAccount: any,
    loansAccountTemplate: any,
    calendarOptions: any,
    locale: string,
    dateFormat: string
  ): any {
    const loansAccountData = {
      ...loansAccount,
      charges: (loansAccount.charges ?? [])
        .map((charge: any) => {
          const chargeId = charge.chargeId ?? charge.id;
          if (chargeId == null) {
            return null;
          }
          const mappedCharge: any = {
            chargeId,
            amount: charge.amount
          };
          if (charge.id && charge.id !== chargeId) {
            mappedCharge.id = charge.id;
          }
          if (charge.dueDate) {
            mappedCharge.dueDate = this.dateUtils.formatDate(charge.dueDate, dateFormat);
          }
          if (charge.feeInterval !== undefined) {
            mappedCharge.feeInterval = charge.feeInterval;
          }
          if (charge.feeOnMonthDay !== undefined) {
            mappedCharge.feeOnMonthDay = charge.feeOnMonthDay;
          }
          return mappedCharge;
        })
        .filter(Boolean),
      disbursementData: loansAccount.disbursementData.map((item: any) => ({
        expectedDisbursementDate: this.dateUtils.formatDate(item.expectedDisbursementDate, dateFormat),
        principal: item.principal
      })),
      interestChargedFromDate: this.dateUtils.formatDate(loansAccount.interestChargedFromDate, dateFormat),
      repaymentsStartingFromDate: this.dateUtils.formatDate(loansAccount.repaymentsStartingFromDate, dateFormat),
      submittedOnDate: this.dateUtils.formatDate(loansAccount.submittedOnDate, dateFormat),
      expectedDisbursementDate: this.dateUtils.formatDate(loansAccount.expectedDisbursementDate, dateFormat),
      dateFormat,
      locale
    };

    if (loansAccount.collateral) {
      loansAccountData.collateral = loansAccount.collateral.map((collateralEle: any) => ({
        clientCollateralId: collateralEle.type.collateralId,
        quantity: collateralEle.value
      }));
    }

    if (loansAccountTemplate.clientId && loansAccountTemplate.group?.id) {
      loansAccountData.clientId = loansAccountTemplate.clientId;
      loansAccountData.groupId = loansAccountTemplate.group.id;
      loansAccountData.loanType = 'glim';
    } else if (loansAccountTemplate.clientId) {
      loansAccountData.clientId = loansAccountTemplate.clientId;
      loansAccountData.loanType = 'individual';
    } else {
      loansAccountData.groupId = loansAccountTemplate.group.id;
      loansAccountData.loanType = 'group';
    }

    if (loansAccountData.syncRepaymentsWithMeeting) {
      loansAccountData.calendarId = calendarOptions[0].id;
      delete loansAccountData.syncRepaymentsWithMeeting;
    }

    if (loansAccountData.recalculationRestFrequencyDate) {
      loansAccountData.recalculationRestFrequencyDate = this.dateUtils.formatDate(
        loansAccount.recalculationRestFrequencyDate,
        dateFormat
      );
    }

    if (loansAccountData.interestCalculationPeriodType === 0) {
      loansAccountData.allowPartialPeriodInterestCalculation = false;
    }
    if (!(loansAccountData.isFloatingInterestRate === false)) {
      delete loansAccountData.isFloatingInterestRate;
    }
    if (!loansAccountData.multiDisburseLoan) {
      delete loansAccountData.disbursementData;
    }
    delete loansAccountData.isValid;
    loansAccountData.principal = loansAccountData.principalAmount;
    delete loansAccountData.principalAmount;
    delete loansAccountData.multiDisburseLoan; // this was just added so that disbursement data can be send in the backend

    // In Fineract, the POST and PUT endpoints for /v1/loans have a typo in the field
    // allowPartialPeriodInterestCalculation. Until that is fixed, we need to replace the field name in the payload.
    loansAccountData.allowPartialPeriodInterestCalcualtion = loansAccountData.allowPartialPeriodInterestCalculation;
    delete loansAccountData.allowPartialPeriodInterestCalculation;
    return loansAccountData;
  }

  saveLoanDisbursementDetailsData(disbursementData: DisbursementData[]): void {
    localStorage.setItem('disbursementData', JSON.stringify(disbursementData));
  }

  getLoanDisbursementDetailsData(): DisbursementData[] {
    return JSON.parse(localStorage.getItem('disbursementData'));
  }
}

/** Angular Imports */
import { Injectable, inject } from '@angular/core';
import { HttpEvent, HttpInterceptor, HttpHandler, HttpRequest } from '@angular/common/http';

/** rxjs Imports */
import { Observable } from 'rxjs';

/** Environment Configuration */
import { SettingsService } from 'app/settings/settings.service';

/**
 * Http request interceptor to prefix a request with `serverUrl`.
 */
@Injectable()
export class ApiPrefixInterceptor implements HttpInterceptor {
  private settingsService = inject(SettingsService);

  /**
   * Intercepts a Http request and prefixes it with `serverUrl`.
   */
  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    let baseUrl = this.settingsService.serverUrl;

    const versionRegex = /^\/(v[1-9][0-9]*\/).*$/;
    if (versionRegex.test(request.url)) {
      baseUrl = this.settingsService.baseServerUrl;
    }
    if (request.url.includes('/actuator/')) {
      baseUrl = this.settingsService.serverHost;
    }

    /**
     * Ignore URLs that are complete for i18n
     * **__NOTE__** OAuth2 endpoints are handled by angular-oauth2-oidc library
     */
    if (!request.url.includes('http:') && !request.url.includes('https:')) {
      request = request.clone({ url: baseUrl + request.url });
    }
    return next.handle(request);
  }
}

/* eslint-disable @angular-eslint/prefer-inject */
/** Angular Imports */
import { Inject, Injectable, InjectionToken, Injector, Optional } from '@angular/core';
import { HttpClient, HttpEvent, HttpInterceptor, HttpHandler, HttpRequest } from '@angular/common/http';

/** rxjs Imports */
import { Observable } from 'rxjs';

/** Custom Interceptors */
import { ErrorHandlerInterceptor } from './error-handler.interceptor';
import { CacheInterceptor } from './cache.interceptor';
import { ApiPrefixInterceptor } from './api-prefix.interceptor';

/**
 * HttpClient is declared in a re-exported module, so we have to extend the original module to make it work properly.
 * (see https://github.com/Microsoft/TypeScript/issues/13897)
 */
declare module '@angular/common/http' {
  /**
   * Augment HttpClient with the added configuration methods from HttpService, to allow in-place replacement of
   * HttpClient with HttpService using dependency injection.
   */
  export interface HttpClient {
    /**
     * Enables caching for this request.
     * @param {boolean} forceUpdate Forces request to be made and updates cache entry.
     * @returns {HttpClient} The new instance.
     */
    cache(forceUpdate?: boolean): HttpClient;

    /**
     * Skips default error handler for this request.
     * @returns {HttpClient} The new instance.
     */
    skipErrorHandler(): HttpClient;

    /**
     * Do not use API prefix for this request.
     * @returns {HttpClient} The new instance.
     */
    disableApiPrefix(): HttpClient;
  }
}

/**
 *  From @angular/common/http/src/interceptor: allows to chain interceptors
 */
class HttpInterceptorHandler implements HttpHandler {
  constructor(
    private next: HttpHandler,
    private interceptor: HttpInterceptor
  ) {}

  handle(request: HttpRequest<any>): Observable<HttpEvent<any>> {
    return this.interceptor.intercept(request, this.next);
  }
}

/**
 * Allows to override default dynamic interceptors that can be disabled with the HttpService extension.
 * Except for very specific needs, you should better configure these interceptors directly in the constructor below
 * for better readability.
 *
 * For static interceptors that should always be enabled (like ApiPrefixInterceptor), use the standard
 * HTTP_INTERCEPTORS token.
 */
export const HTTP_DYNAMIC_INTERCEPTORS = new InjectionToken<HttpInterceptor>('HTTP_DYNAMIC_INTERCEPTORS');

/**
 * Extends HttpClient with per request configuration using dynamic interceptors.
 */
@Injectable()
export class HttpService extends HttpClient {
  constructor(
    private httpHandler: HttpHandler,
    private injector: Injector,
    @Optional() @Inject(HTTP_DYNAMIC_INTERCEPTORS) private interceptors: HttpInterceptor[] = []
  ) {
    super(httpHandler);

    if (!this.interceptors) {
      // Configure default interceptors that can be disabled here
      this.interceptors = [
        this.injector.get(ApiPrefixInterceptor),
        this.injector.get(ErrorHandlerInterceptor)
      ];
    }
  }

  cache(forceUpdate?: boolean): HttpClient {
    const cacheInterceptor = this.injector.get(CacheInterceptor).configure({ update: forceUpdate });
    return this.addInterceptor(cacheInterceptor);
  }

  skipErrorHandler(): HttpClient {
    return this.removeInterceptor(ErrorHandlerInterceptor);
  }

  disableApiPrefix(): HttpClient {
    return this.removeInterceptor(ApiPrefixInterceptor);
  }

  /**
   *  Override the original method to wire interceptors when triggering the request.
   */
  request(method?: any, url?: any, options?: any): any {
    const handler = this.interceptors.reduceRight(
      (next, interceptor) => new HttpInterceptorHandler(next, interceptor),
      this.httpHandler
    );
    return new HttpClient(handler).request(method, url, options);
  }

  private removeInterceptor(interceptorType: Function): HttpService {
    return new HttpService(
      this.httpHandler,
      this.injector,
      this.interceptors.filter((i) => !(i instanceof interceptorType))
    );
  }

  private addInterceptor(interceptor: HttpInterceptor): HttpService {
    return new HttpService(this.httpHandler, this.injector, this.interceptors.concat([interceptor]));
  }
}

/** Angular Imports */
import { Injectable, inject } from '@angular/core';
import { HttpEvent, HttpInterceptor, HttpHandler, HttpRequest } from '@angular/common/http';

/** rxjs Imports */
import { Observable } from 'rxjs';

/** Custom Imports */
import { environment } from '../../../environments/environment';
import { SettingsService } from 'app/settings/settings.service';

/** Http request (default) options headers. */
const httpOptions: { headers: { [key: string]: string } } = {
  headers: {
    'Fineract-Platform-TenantId': environment.fineractPlatformTenantId
  }
};

/** Authorization header. */
const authorizationHeader = 'Authorization';
const authorizationTenantHeader = 'Fineract-Platform-TenantId';
/** Two factor access token header. */
const twoFactorAccessTokenHeader = 'Fineract-Platform-TFA-Token';

/**
 * Http Request interceptor to set the request headers.
 */
@Injectable()
export class AuthenticationInterceptor implements HttpInterceptor {
  private settingsService = inject(SettingsService);

  /**
   * Intercepts a Http request and sets the request headers.
   */
  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    if (this.settingsService.tenantIdentifier) {
      httpOptions.headers['Fineract-Platform-TenantId'] = this.settingsService.tenantIdentifier;
    }
    request = request.clone({ setHeaders: httpOptions.headers });
    return next.handle(request);
  }

  /**
   * Sets the basic/oauth authorization header depending on the configuration.
   * @param {string} authenticationKey Authentication key.
   */
  setAuthorizationToken(authenticationKey: string) {
    if (environment.oauth.enabled) {
      httpOptions.headers[authorizationHeader] = `Bearer ${authenticationKey}`;
    } else {
      httpOptions.headers[authorizationHeader] = `Basic ${authenticationKey}`;
    }
  }

  /**
   * Sets the two factor access token header.
   * @param {string} twoFactorAccessToken Two factor access token.
   */
  setTwoFactorAccessToken(twoFactorAccessToken: string) {
    httpOptions.headers[twoFactorAccessTokenHeader] = twoFactorAccessToken;
  }

  /**
   * Removes the authorization header.
   */
  removeAuthorization() {
    delete httpOptions.headers[authorizationHeader];
  }

  /**
   * Removes the authorization header.
   */
  removeAuthorizationTenant() {
    delete httpOptions.headers[authorizationHeader];
    delete httpOptions.headers[authorizationTenantHeader];
  }

  /**
   * Removes the two factor access token header.
   */
  removeTwoFactorAuthorization() {
    delete httpOptions.headers[twoFactorAccessTokenHeader];
  }
}

/** Angular Imports */
import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams, HttpHeaders } from '@angular/common/http';
/** rxjs Imports */
import { BehaviorSubject, Observable, of } from 'rxjs';
import { map } from 'rxjs/operators';

/** 3rd party Imports */
import { OAuthService } from 'angular-oauth2-oidc';
/** Custom Services */
import { AlertService } from '../alert/alert.service';

/** Custom Interceptors */
import { AuthenticationInterceptor } from './authentication.interceptor';

/** Environment Configuration */
import { environment } from '../../../environments/environment';

/** Custom Models */
import { LoginContext } from './login-context.model';
import { Credentials } from './credentials.model';
import { getOAuthConfig, getActiveAuthMode, AuthMode } from './oauth.config';

/**
 * Authentication workflow.
 */
@Injectable()
export class AuthenticationService {
  private http = inject(HttpClient);
  private alertService = inject(AlertService);
  private authenticationInterceptor = inject(AuthenticationInterceptor);
  private oauthService = inject(OAuthService);

  /**
   * Updates the password for the specified user.
   * @param {string} userId Target user identifier.
   * @param {*} passwordObj Payload containing the new password fields.
   * @returns Updated user response observable.
   */
  changePassword(userId: string, passwordObj: any) {
    return this.http.put(`/users/${userId}`, passwordObj);
  }

  private userLoggedIn$: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);
  /** Observable that emits authentication state changes. */
  public readonly isAuthenticated$ = this.userLoggedIn$.asObservable();

  /** Denotes whether the user credentials should persist through sessions. */
  private rememberMe = false;
  /**
   * Denotes the type of storage:
   *
   * Session Storage: User credentials should not persist through sessions.
   *
   * Local Storage: User credentials should persist through sessions.
   */
  private storage: Storage = sessionStorage;
  private credentials: Credentials;
  private dialogShown = false;
  private authMode: AuthMode = AuthMode.Basic;

  /** Key to store credentials in storage. */
  private readonly credentialsStorageKey = 'mifosXCredentials';
  /** Key to store two factor authentication token in storage. */
  private readonly twoFactorAuthenticationTokenStorageKey = 'mifosXTwoFactorAuthenticationToken';

  /**
   * Initializes the type of storage and authorization headers depending on whether
   * credentials are presently in storage or not.
   * @param {HttpClient} http Http Client to send requests.
   * @param {AlertService} alertService Alert Service.
   * @param {AuthenticationInterceptor} authenticationInterceptor Authentication Interceptor.
   * @param {OAuthService} oauthService OAuth Service.
   */
  constructor() {
    this.authMode = getActiveAuthMode();

    if (this.authMode !== AuthMode.Basic) {
      this.initializeOAuthService();
    }

    this.restoreSession();
  }

  /**
   * Configures the OAuth service with runtime settings and hooks up token listeners.
   */
  private initializeOAuthService(): void {
    this.oauthService.configure(getOAuthConfig());
    const oauthStorage = environment.enableRememberMe ? localStorage : sessionStorage;
    this.oauthService.setStorage(oauthStorage);
    this.oauthService.setupAutomaticSilentRefresh();

    this.oauthService.events.subscribe((event) => {
      if (event.type === 'token_received' || event.type === 'token_refreshed') {
        this.updateCredentialsToken();
      }
    });

    this.cleanupLegacyStorage();
  }

  /**
   * Restores persisted credentials/tokens from storage and rehydrates the session state.
   */
  private restoreSession(): void {
    const savedCredentials = this.getSavedCredentials();
    if (!savedCredentials) return;

    if (savedCredentials.rememberMe) {
      this.rememberMe = true;
      this.storage = localStorage;
      this.oauthService.setStorage(this.storage);
    }

    if (this.authMode !== AuthMode.Basic) {
      // OAuth2/OIDC: Use angular-oauth2-oidc library for token management
      if (this.oauthService.hasValidAccessToken()) {
        this.authenticationInterceptor.setAuthorizationToken(this.oauthService.getAccessToken());
        this.userLoggedIn$.next(true);
      } else if (this.oauthService.getRefreshToken()) {
        this.oauthService
          .refreshToken()
          .then(() => this.userLoggedIn$.next(true))
          .catch(() => this.logout().subscribe());
      }
    } else {
      // Basic Auth
      this.authenticationInterceptor.setAuthorizationToken(savedCredentials.base64EncodedAuthenticationKey);

      const twoFactorToken = JSON.parse(this.storage.getItem(this.twoFactorAuthenticationTokenStorageKey));
      if (twoFactorToken) {
        this.authenticationInterceptor.setTwoFactorAccessToken(twoFactorToken.token);
      }

      this.userLoggedIn$.next(true);
    }
  }

  /**
   * Persists the latest OAuth access token in both the interceptor and stored credentials.
   */
  private updateCredentialsToken(): void {
    const accessToken = this.oauthService.getAccessToken();
    if (!accessToken) return;

    this.authenticationInterceptor.setAuthorizationToken(accessToken);

    const credentials = this.getCredentials();
    if (credentials) {
      credentials.accessToken = accessToken;
      this.storage.setItem(this.credentialsStorageKey, JSON.stringify(credentials));
    }
  }

  /**
   * Reads the cached credentials from session or local storage, if present.
   * @returns {Credentials | null} Stored credentials or null when absent.
   */
  private getSavedCredentials(): Credentials | null {
    const stored =
      sessionStorage.getItem(this.credentialsStorageKey) || localStorage.getItem(this.credentialsStorageKey);
    return stored ? JSON.parse(stored) : null;
  }

  /**
   * Authenticates the user.
   * @param {LoginContext} loginContext Login parameters.
   * @returns {Observable<boolean>} True if authentication is successful.
   */
  login(loginContext?: LoginContext): Observable<boolean> {
    this.alertService.alert({ type: 'Authentication Start', message: 'Please wait...' });

    if (this.authMode !== AuthMode.Basic) {
      // OAuth2/OIDC: Redirect to authorization server with PKCE
      this.oauthService.initCodeFlow();
      return of(true);
    }

    if (!loginContext) {
      throw new Error('loginContext is required when using Basic authentication');
    }

    this.rememberMe = environment.enableRememberMe ? (loginContext?.remember ?? false) : false;
    this.storage = this.rememberMe ? localStorage : sessionStorage;

    // Basic Auth: Direct authentication with Fineract
    return this.http
      .post('/authentication', {
        username: loginContext.username,
        password: loginContext.password,
        remember: this.rememberMe
      })
      .pipe(
        map((credentials: Credentials) => {
          this.onLoginSuccess(credentials);
          return true;
        })
      );
  }

  /**
   * Fetches user details from the server.
   * @returns {Promise<void>} Promise that resolves when user details are fetched.
   */
  private async getUserDetails(): Promise<void> {
    const accessToken = this.oauthService.getAccessToken();

    return new Promise((resolve, reject) => {
      if (this.authMode === AuthMode.OIDC) {
        const url = `${environment.OIDC.oidcApiUrl}authentication/userdetails`;
        this.http.post<{ object: Credentials }>(url, { token: accessToken }).subscribe({
          next: (response) => {
            const credentials = response.object;
            credentials.accessToken = accessToken;
            this.onLoginSuccess(credentials);
            resolve();
          },
          error: (error) => {
            console.error('Failed to fetch user details:', error);
            reject(error);
          }
        });
      } else if (this.authMode === AuthMode.OAuth2) {
        const headers = new HttpHeaders().set('Authorization', `Bearer ${accessToken}`);
        const url = `${environment.oauth.serverUrl}/userdetails`;
        this.http.get<Credentials>(url, { headers }).subscribe({
          next: (credentials) => {
            credentials.accessToken = accessToken;
            this.onLoginSuccess(credentials);
            resolve();
          },
          error: (error) => {
            console.error('Failed to fetch user details:', error);
            reject(error);
          }
        });
      }
    });
  }

  /**
   * Sets the authorization token followed by one of the following:
   *
   * Sends an alert if two factor authentication is required.
   *
   * Sends an alert if password has expired and requires a reset.
   *
   * Sends an alert on successful login.
   * @param {Credentials} credentials Authenticated user credentials.
   */
  private onLoginSuccess(credentials: Credentials): void {
    this.userLoggedIn$.next(true); // ✅ notify observers
    // Ensure the rememberMe value is preserved in credentials
    credentials.rememberMe = this.rememberMe;

    if (this.authMode !== AuthMode.Basic) {
      this.authenticationInterceptor.setAuthorizationToken(credentials.accessToken);
    } else {
      this.authenticationInterceptor.setAuthorizationToken(credentials.base64EncodedAuthenticationKey);
    }
    if (credentials.isTwoFactorAuthenticationRequired) {
      this.credentials = credentials;
      this.alertService.alert({
        type: 'Two Factor Authentication Required',
        message: 'Two Factor Authentication Required'
      });
    } else {
      if (credentials.shouldRenewPassword) {
        this.credentials = credentials;
        this.alertService.alert({
          type: 'Password Expired',
          message: 'Your password has expired, please reset your password!'
        });
      } else {
        this.setCredentials(credentials);
        this.alertService.alert({
          type: 'Authentication Success',
          message: `${credentials.username} successfully logged in!`
        });
        delete this.credentials;
      }
    }
  }

  /**
   * Handles the OAuth callback.
   * @returns {Promise<boolean>} True if the OAuth callback was successful.
   */
  async handleOAuthCallback(): Promise<boolean> {
    try {
      // index.html preserves the OAuth callback query string in sessionStorage before redirecting to /#/callback, since Angular routing consumes query params before the OAuth library can process them.
      let queryString = sessionStorage.getItem('oauth_callback_query');

      if (queryString) {
        sessionStorage.removeItem('oauth_callback_query');
        await this.oauthService.tryLoginCodeFlow({ customHashFragment: queryString });
      } else {
        await this.oauthService.tryLoginCodeFlow();
      }

      if (this.oauthService.hasValidAccessToken()) {
        await this.getUserDetails();
        return true;
      }

      return false;
    } catch (error) {
      console.error('OAuth callback failed:', error);
      return false;
    }
  }

  /**
   * Logs out the authenticated user and clears the credentials from storage.
   * @returns {Observable<boolean>} True if the user was logged out successfully.
   */
  logout(): Observable<boolean> {
    const twoFactorToken = JSON.parse(this.storage.getItem(this.twoFactorAuthenticationTokenStorageKey));
    if (twoFactorToken) {
      this.http.post('/twofactor/invalidate', { token: twoFactorToken.token }).subscribe();
      this.authenticationInterceptor.removeTwoFactorAuthorization();
    }

    // Clear any pending OAuth callback data
    sessionStorage.removeItem('oauth_callback_query');

    this.authenticationInterceptor.removeAuthorization();
    this.setCredentials();
    this.resetDialog();
    this.userLoggedIn$.next(false);

    if (this.authMode === AuthMode.OIDC) {
      // OIDC: Use library to handle logout (redirects to OIDC provider)
      this.oauthService.logOut();
    } else if (this.authMode === AuthMode.OAuth2) {
      // OAuth2 (Fineract): Clear library tokens and server session
      this.oauthService.logOut(true); // true = don't redirect
      // Call Fineract logout endpoint in a popup to clear server session (includes JSESSIONID cookie)
      // Then close the popup and navigate to login page
      const logoutWindow = window.open(environment.oauth.logoutUrl, '_blank', 'width=100,height=100');
      setTimeout(() => {
        if (logoutWindow) {
          logoutWindow.close();
        }
        window.location.href = `${window.location.origin}/#/login`;
      }, 500);
    }
    return of(true);
  }

  /**
   * Checks if the two factor access token for authenticated user is valid.
   * @returns {boolean} True if the two factor access token is valid or two factor authentication is not required.
   */
  twoFactorAccessTokenIsValid(): boolean {
    const twoFactorAccessToken = JSON.parse(this.storage.getItem(this.twoFactorAuthenticationTokenStorageKey));
    if (twoFactorAccessToken) {
      return new Date().getTime() < twoFactorAccessToken.validTo;
    }
    return true;
  }

  /**
   * Checks if the user is authenticated.
   * @returns {boolean} True if the user is authenticated.
   */
  isAuthenticated(): boolean {
    if (this.authMode !== AuthMode.Basic) {
      return this.oauthService.hasValidAccessToken();
    }
    return !!(this.getSavedCredentials() && this.twoFactorAccessTokenIsValid());
  }

  /**
   * Gets the user credentials.
   * @returns {Credentials} The user credentials if the user is authenticated otherwise null.
   */
  getCredentials(): Credentials | null {
    return JSON.parse(this.storage.getItem(this.credentialsStorageKey));
  }

  /**
   * Sets the user credentials.
   *
   * The credentials may be persisted across sessions by setting the `rememberMe` parameter to true.
   * Otherwise, the credentials are only persisted for the current session.
   *
   * @param {Credentials} credentials Authenticated user credentials.
   */
  private setCredentials(credentials?: Credentials): void {
    if (credentials) {
      credentials.rememberMe = this.rememberMe;
      // Make sure we're using the correct storage based on rememberMe value
      this.storage = credentials.rememberMe ? localStorage : sessionStorage;
      this.oauthService.setStorage(this.storage);
      this.storage.setItem(this.credentialsStorageKey, JSON.stringify(credentials));
    } else {
      // Clear credentials from both storage types to ensure complete logout
      [
        localStorage,
        sessionStorage
      ].forEach((store) => {
        store.removeItem(this.credentialsStorageKey);
        store.removeItem(this.twoFactorAuthenticationTokenStorageKey);
      });
      this.cleanupLegacyStorage();
    }
  }

  private cleanupLegacyStorage(): void {
    const legacyKeys = [
      'mifosXZitadelTokenDetails',
      'mifosXOAuthTokenDetails',
      'token_start_time',
      'refresh_expires_in',
      'mifosXZitadel',
      'auth_code'
      // Note: Do NOT remove 'PKCE_verifier' here - it's needed by angular-oauth2-oidc for the callback
    ];
    legacyKeys.forEach((key) => {
      localStorage.removeItem(key);
      sessionStorage.removeItem(key);
    });
  }

  /**
   * Following functions are for two factor authentication and require
   * first level authorization headers to be setup for the requests.
   */

  /**
   * Gets the two factor authentication delivery methods available for the user.
   */
  getDeliveryMethods() {
    return this.http.get('/twofactor');
  }

  showDialog() {
    this.dialogShown = true;
  }

  resetDialog() {
    this.dialogShown = false;
  }

  hasDialogBeenShown() {
    return this.dialogShown;
  }

  /**
   * Requests OTP to be sent via the given delivery method.
   * @param {any} deliveryMethod Delivery method for the OTP.
   */
  requestOTP(deliveryMethod: any) {
    let httpParams = new HttpParams();
    httpParams = httpParams.set('deliveryMethod', deliveryMethod.name);
    httpParams = httpParams.set('extendedToken', this.rememberMe.toString());
    return this.http.post(`/twofactor`, {}, { params: httpParams });
  }

  /**
   * Validates the OTP and authenticates the user on success.
   * @param {string} otp
   */
  validateOTP(otp: string) {
    const httpParams = new HttpParams().set('token', otp);
    return this.http.post(`/twofactor/validate`, {}, { params: httpParams }).pipe(
      map((response) => {
        this.onOTPValidateSuccess(response);
      })
    );
  }

  /**
   * Sets the two factor authorization token followed by one of the following:
   *
   * Sends an alert if password has expired and requires a reset.
   *
   * Sends an alert on successful login.
   * @param {any} response Two factor authentication token details.
   */
  private onOTPValidateSuccess(response: any): void {
    this.authenticationInterceptor.setTwoFactorAccessToken(response.token);
    if (this.credentials.shouldRenewPassword) {
      this.alertService.alert({
        type: 'Password Expired',
        message: 'Your password has expired, please reset your password!'
      });
    } else {
      this.setCredentials(this.credentials);
      this.alertService.alert({
        type: 'Authentication Success',
        message: `${this.credentials.username} successfully logged in!`
      });
      delete this.credentials;
      this.storage.setItem(this.twoFactorAuthenticationTokenStorageKey, JSON.stringify(response));
    }
  }

  /**
   * Resets the user's password and authenticates the user.
   * @param {any} passwordDetails New password.
   */
  resetPassword(passwordDetails: any) {
    return this.http.put(`/users/${this.credentials.userId}`, passwordDetails).pipe(
      map(() => {
        this.alertService.alert({ type: 'Password Reset Success', message: `Your password was sucessfully reset!` });
        this.authenticationInterceptor.removeAuthorization();
        this.authenticationInterceptor.removeTwoFactorAuthorization();
        const loginContext: LoginContext = {
          username: this.credentials.username,
          password: passwordDetails.password,
          remember: this.rememberMe
        };
        this.login(loginContext).subscribe();
      })
    );
  }

  /*
   * Get user logged in
   */
  getUserLoggedIn(): boolean {
    return this.userLoggedIn$.value;
  }
}

/** Angular Imports */
import { Injectable, inject } from '@angular/core';
import { AlertService } from 'app/core/alert/alert.service';
import { Dates } from 'app/core/utils/dates';

/** Environment Imports */
import { environment } from '../../environments/environment';

/**
 * Settings Service
 */
@Injectable({
  providedIn: 'root'
})
export class SettingsService {
  private alertService = inject(AlertService);
  private dateUtils = inject(Dates);

  public static businessDateFormat = 'yyyy-MM-dd';
  public static businessDateConfigName = 'enable-business-date';
  public static businessDateType = 'BUSINESS_DATE';
  public static cobDateType = 'COB_DATE';
  minAllowedDate = new Date(1950, 0, 1);
  maxAllowedDate = new Date(2100, 0, 1);

  /**
   * Sets date format setting throughout the app.
   * @param {string} dateFormat Date Format
   */
  setDateFormat(dateFormat: string) {
    localStorage.setItem('mifosXDateFormat', JSON.stringify(dateFormat));
  }

  /**
   * Sets language setting throughout the app.
   * @param {any} language Language.
   */
  setLanguage(language: { name: string; code: string }) {
    localStorage.setItem('mifosXLanguage', JSON.stringify(language));
  }

  /**
   * Sets decimals to Display throughout the app.
   * @param {string} decimals.
   */
  setDecimalToDisplay(decimals: string) {
    localStorage.setItem('mifosXDecimalsToDisplay', decimals);
  }

  setDefaultLanguage() {
    const defaultLanguage = environment.defaultLanguage ? environment.defaultLanguage : 'en-US';
    this.setLanguage({
      name: defaultLanguage,
      code: defaultLanguage.substring(0, 2)
    });
  }

  /**
   * Sets server URL setting throughout the app.
   * @param {string} url URL
   */
  setServer(url: string) {
    localStorage.setItem('mifosXServerURL', url);
  }

  /**
   * Sets server URL setting throughout the app.
   * @param {string[]} list List of default servers
   */
  setServers(list: string[]) {
    localStorage.setItem('mifosXServers', JSON.stringify(list));
  }

  /**
   * Sets Tenant Identifiers list setting throughout the app.
   * @param {string[]} list List of default tenants
   */
  setTenantIdentifiers(list: string[]) {
    localStorage.setItem('mifosXTenantIdentifiers', JSON.stringify(list));
  }

  /**
   * Sets Tenant Identifier setting throughout the app.
   * @param {string} Tenant Identifier
   */
  setTenantIdentifier(tenantIdentifier: string) {
    localStorage.setItem('mifosXTenantIdentifier', tenantIdentifier);
  }

  /**
   * Sets server Date setting for max datepicker, default today
   * @param {string} date
   */
  setBusinessDate(date: string) {
    localStorage.setItem('mifosXServerDate', date);
  }

  /**
   * Sets server Date config is enabled
   * @param {string} enabled
   */
  setBusinessDateConfig(enabled: string) {
    localStorage.setItem('mifosXServerBusinessDateEnabled', enabled);
  }

  /**
   * Returns date format setting.
   */
  get dateFormat() {
    return JSON.parse(localStorage.getItem('mifosXDateFormat'));
  }

  /**
   * Returns language setting
   */
  get language() {
    if (!localStorage.getItem('mifosXLanguage')) {
      this.setDefaultLanguage();
    }
    return JSON.parse(localStorage.getItem('mifosXLanguage'));
  }

  get languageCode() {
    const currentLanguage = this.language.code;
    if (currentLanguage === 'es') {
      return 'es-MX';
    }
    if (currentLanguage === 'en') {
      return 'en-US';
    }
    return currentLanguage + '-' + currentLanguage.toUpperCase();
  }

  /**
   * Returns Decimals to Display setting
   */
  get decimals() {
    if (!localStorage.getItem('mifosXDecimalsToDisplay')) {
      return '2';
    }
    return localStorage.getItem('mifosXDecimalsToDisplay');
  }

  /**
   * Returns list of default server
   */
  get servers() {
    return JSON.parse(localStorage.getItem('mifosXServers'));
  }

  /**
   * Returns server setting
   */
  get server() {
    if (localStorage.getItem('mifosXServerURL')) {
      return localStorage.getItem('mifosXServerURL');
    }
    if (environment.baseApiUrl && environment.baseApiUrl !== '') {
      return environment.baseApiUrl;
    } else {
      return this.servers()[0];
    }
  }

  /**
   * Returns server url with api path without version
   */
  get baseServerUrl() {
    return this.server + environment.apiProvider;
  }

  /**
   * Returns server url with api path and version
   */
  get serverUrl() {
    return this.server + environment.apiProvider + environment.apiVersion;
  }

  /**
   * Returns server url with api path and version
   */
  get serverHost() {
    return this.server;
  }

  /**
   * Returns current Business date server
   */
  get businessDate(): Date {
    return this.dateUtils.convertToDate(localStorage.getItem('mifosXServerDate'), SettingsService.businessDateFormat);
  }

  /**
   * Returns current Business date Config if it's enabled
   */
  get businessDateConfig(): any {
    return localStorage.getItem('mifosXServerBusinessDateEnabled');
  }

  /**
   * Returns min Past date
   */
  get minPastDate(): Date {
    return this.minAllowedDate;
  }

  /**
   * Returns max Future date
   */
  get maxFutureDate(): Date {
    return this.maxAllowedDate;
  }

  /**
   * Returns list of Tenant Identifiers
   */
  get tenantIdentifiers(): any {
    return JSON.parse(localStorage.getItem('mifosXTenantIdentifiers'));
  }

  /**
   * Returns Tenant Identifier
   */
  get tenantIdentifier(): string {
    return localStorage.getItem('mifosXTenantIdentifier');
  }

  /**
   * Validate If the enable_business_date configuration is enabled or disabled.
   */
  validateBusinessDateStatus(configurations: any) {
    configurations.some((config: any) => {
      if (config.name === SettingsService.businessDateConfigName) {
        return config.enabled;
      }
    });
  }

  /**
   * Get the Business Date or COB Date.
   */
  getBusinessDates(businessDateData: any, dateType: string): void {
    businessDateData.some((data: any) => {
      if (data.type === dateType) {
        const dateVal = new Date(data.date);
        this.setBusinessDate(this.dateUtils.formatDate(dateVal, SettingsService.businessDateFormat));
        this.alertService.alert({
          type: dateType + ' Set',
          message: this.dateUtils.formatDate(dateVal, this.dateFormat)
        });
        return;
      }
    });
  }

  setThemeDarkEnabled(enabled: boolean) {
    localStorage.setItem('mifosXThemeDarkEnabled', JSON.stringify(enabled));
  }

  get themeDarkEnabled(): boolean {
    return JSON.parse(localStorage.getItem('mifosXThemeDarkEnabled'));
  }
}

